We have discussed the implementation of QuickSort using Lomuto partition scheme. Lomuto's partition scheme is easy to implement as compared to Hoare scheme. This has inferior performance to Hoare's QuickSort.Lomuto's Partition Scheme - O(n) Time and O(1) Auxiliary SpaceThis algorithm works by assuming the pivot element as the last element. If any other element is given as a pivot element then swap it first with the last element. Now initialize two variables i as low and j also low,  iterate over the array and increment i when arr[j] <= pivot and swap arr[i] with arr[j] otherwise increment only j. After coming out from the loop swap arr[i+1] with arr[hi]. This i stores the pivot element.Algorithm:partition(arr[], lo, hi)     pivot = arr[hi]    i = lo-1     // place for swapping    for j := lo to hi – 1 do        if arr[j] <= pivot then            i = i + 1             swap arr[i] with arr[j]    swap arr[i+1] with arr[hi]    return i+1Refer QuickSort for details of this partitioning scheme. Below are implementations of this approach:-
            C++

    #include <bits/stdc++.h>
using namespace std;

/* This function takes the last element as pivot, places
   the pivot element at its correct position in sorted
   array, and places all smaller (smaller than pivot)
   to the left of the pivot and all greater elements
   to the right  of the pivot */
int partition(vector<int> &arr, int low, int high)
{
    int pivot = arr[high]; // pivot
    int i = (low - 1);     // Index of smaller element

    for (int j = low; j <= high - 1; j++)
    {
        // If current element is smaller than or
        // equal to pivot
        if (arr[j] <= pivot)
        {
            i++; // increment index of smaller element
            swap(arr[i], arr[j]);
        }
    }
    swap(arr[i + 1], arr[high]);
    return (i + 1);
}

/* The main function that implements QuickSort
 arr[] --> Array to be sorted,
  low  --> Starting index,
  high  --> Ending index */
void quickSort(vector<int> &arr, int low, int high)
{
    if (low < high)
    {
        /* pi is partitioning index, arr[p] is now
           at right place */
        int pi = partition(arr, low, high);

        // Separately sort elements before
        // partition and after partition
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

/* Function to print an array */
void printArray(const vector<int> &arr)
{
    for (int i : arr)
        cout << i << " ";
    cout << endl;
}

// Driver program to test above functions
int main()
{
    vector<int> arr = {10, 7, 8, 9, 1, 5};
    int n = arr.size();
    quickSort(arr, 0, n - 1);
    cout << "Sorted array: \n";
    printArray(arr);
    return 0;
}


